-- ==========================================
-- E-Commerce Database - Rich Schema + 90k+ Rows (MySQL 8.4)
-- Generated: 2025-08-24 05:00:10
-- ==========================================

DROP DATABASE IF EXISTS ecommerce_project_rich;
CREATE DATABASE ecommerce_project_rich;
USE ecommerce_project_rich;

-- ========== Tables ==========

CREATE TABLE users (
  user_id INT PRIMARY KEY,
  first_name VARCHAR(50),
  last_name VARCHAR(50),
  email VARCHAR(120) UNIQUE,
  phone VARCHAR(20),
  password_hash CHAR(64),
  gender ENUM('male','female','other'),
  dob DATE,
  address VARCHAR(255),
  city VARCHAR(100),
  state VARCHAR(100),
  country VARCHAR(100),
  pincode VARCHAR(12),
  created_at DATETIME
);

CREATE TABLE categories (
  category_id INT PRIMARY KEY,
  category_name VARCHAR(100),
  description VARCHAR(255)
);

CREATE TABLE suppliers (
  supplier_id INT PRIMARY KEY,
  supplier_name VARCHAR(150),
  contact_email VARCHAR(120),
  phone VARCHAR(20),
  address VARCHAR(255),
  city VARCHAR(100),
  country VARCHAR(100)
);

CREATE TABLE products (
  product_id INT PRIMARY KEY,
  product_name VARCHAR(150),
  category_id INT,
  supplier_id INT,
  sku VARCHAR(50) UNIQUE,
  description TEXT,
  price DECIMAL(10,2),
  discount DECIMAL(5,2),
  created_at DATETIME,
  FOREIGN KEY (category_id) REFERENCES categories(category_id),
  FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id)
);

CREATE TABLE orders (
  order_id INT PRIMARY KEY,
  user_id INT,
  order_date DATETIME,
  status ENUM('pending','processing','shipped','delivered','cancelled','returned'),
  shipping_address VARCHAR(255),
  billing_address VARCHAR(255),
  total_amount DECIMAL(12,2),
  FOREIGN KEY (user_id) REFERENCES users(user_id)
);

CREATE TABLE order_items (
  order_item_id INT PRIMARY KEY,
  order_id INT,
  product_id INT,
  quantity INT,
  price DECIMAL(10,2),
  discount DECIMAL(5,2),
  FOREIGN KEY (order_id) REFERENCES orders(order_id),
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE payments (
  payment_id INT PRIMARY KEY,
  order_id INT,
  amount DECIMAL(12,2),
  payment_date DATETIME,
  method ENUM('card','upi','netbanking','cod','wallet'),
  transaction_id VARCHAR(100),
  status ENUM('success','pending','failed','refunded'),
  FOREIGN KEY (order_id) REFERENCES orders(order_id)
);

CREATE TABLE shipments (
  shipment_id INT PRIMARY KEY,
  order_id INT,
  tracking_number VARCHAR(100),
  carrier VARCHAR(50),
  shipped_date DATETIME,
  delivery_date DATETIME,
  status ENUM('preparing','in_transit','delivered','delayed','returned'),
  FOREIGN KEY (order_id) REFERENCES orders(order_id)
);

CREATE TABLE reviews (
  review_id INT PRIMARY KEY,
  product_id INT,
  user_id INT,
  rating TINYINT,
  title VARCHAR(150),
  comment VARCHAR(255),
  review_date DATETIME,
  FOREIGN KEY (product_id) REFERENCES products(product_id),
  FOREIGN KEY (user_id) REFERENCES users(user_id)
);

CREATE TABLE inventory (
  inventory_id INT PRIMARY KEY,
  product_id INT,
  stock INT,
  warehouse_location VARCHAR(50),
  last_updated DATETIME,
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);

